// @ts-check
/**
 * T11 tailnet cleartext config plugin.
 *
 * syncd (AflulitAPI) is plain HTTP inside the Tailscale tailnet by design
 * (AflulitAPI deploy/README.md) — Tailscale already encrypts the hop and the
 * backup bodies are themselves AES-GCM envelopes. Android, however, blocks
 * cleartext on a release build by default; Sumrak only ever had
 * `usesCleartextTraffic="true"` in the debug manifests Expo generates, so its
 * home-server target was never proven on a signed build (Sumrak T21 ran on a
 * dev client over `adb reverse`).
 *
 * android/ is generated by `expo prebuild` and gitignored, so the flag can
 * never live there by hand — this plugin sets it on the *main* manifest's
 * <application> on every prebuild, which covers debug and release alike.
 *
 * Why the whole-app flag rather than a network-security-config domain list:
 * the tailnet host is a short MagicDNS name (or a 100.x address) that Mitch
 * edits in Settings, so no domain-config can name it ahead of time. Every
 * other endpoint the app talks to (GitHub, OpenRouter, ElevenLabs) is HTTPS
 * and unaffected; a single-user private app has no third party to protect
 * from a downgrade. Decision recorded in docs-aflulit T11's Session log;
 * T18 re-proves it on the signed release.
 */
const { withAndroidManifest } = require('expo/config-plugins');

/** @param {import('expo/config').ExpoConfig} config */
function withTailnetCleartext(config) {
  return withAndroidManifest(config, (config) => {
    const app = config.modResults.manifest.application?.[0];
    if (!app) throw new Error('with-tailnet-cleartext: no <application> in AndroidManifest.xml');
    app.$ = { ...app.$, 'android:usesCleartextTraffic': 'true' };
    return config;
  });
}

module.exports = withTailnetCleartext;
